import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/** Locales with a catalogue directory; `en` is the source and defines the shape of every other one. */
export const CATALOGUE_LOCALES = ['en', 'de-CH'];

const GENERATED_NOTE =
  '// Generated by tools/i18n-index.mjs (npm run i18n:index). Do not edit by hand.';

/** `regie-scenes` → `regieScenes`, `de-CH` → `deCH`. */
export function camelCase(name) {
  return name.replace(/-+([A-Za-z0-9])/g, (_, char) => char.toUpperCase());
}

/** Catalogue file base names of a locale directory (without `index` and spec files), sorted. */
export function listNamespaces(localeDirectory) {
  if (!existsSync(localeDirectory)) {
    return [];
  }
  return readdirSync(localeDirectory)
    .filter((file) => file.endsWith('.ts') && file !== 'index.ts' && !file.endsWith('.spec.ts'))
    .map((file) => file.slice(0, -'.ts'.length))
    .sort();
}

/** The prefix a catalogue file owns: `regie-scenes` → `regie.scenes`, `common` → `common`. */
export function namespacePrefix(name) {
  return name.replaceAll('-', '.');
}

/** Source of `messages/<locale>/index.ts`: sorted one-per-line imports and a single spread object. */
export function renderIndex(locale, names) {
  const imports = names.map((name) => `import { ${camelCase(name)} } from './${name}';`);
  const spreads = names.map((name) => `  ...${camelCase(name)},`);
  if (locale === 'en') {
    return [
      GENERATED_NOTE,
      ...imports,
      '',
      'export const en = {',
      ...spreads,
      '} as const;',
      '',
    ].join('\n');
  }
  const exportName = camelCase(locale);
  return [
    GENERATED_NOTE,
    "import type { Translation } from '../../types';",
    "import type { en } from '../en';",
    ...imports,
    '',
    `export const ${exportName}: Translation<typeof en> = {`,
    ...spreads,
    '};',
    '',
  ].join('\n');
}

/**
 * Writes or verifies the index of every locale. Returns the problems found (check mode) or the files rewritten.
 * Problems: a locale lacking a file the other has, an index that is missing, stale or damaged by a merge.
 */
export function syncIndexes(messagesDirectory, { check }) {
  const problems = [];
  const written = [];
  const byLocale = new Map(
    CATALOGUE_LOCALES.map((locale) => [locale, listNamespaces(join(messagesDirectory, locale))]),
  );
  const source = byLocale.get('en') ?? [];
  for (const locale of CATALOGUE_LOCALES.slice(1)) {
    const names = byLocale.get(locale) ?? [];
    for (const name of source.filter((n) => !names.includes(n))) {
      problems.push(`messages/${locale}/${name}.ts is missing (the English file exists)`);
    }
    for (const name of names.filter((n) => !source.includes(n))) {
      problems.push(`messages/${locale}/${name}.ts has no English counterpart`);
    }
  }
  for (const [locale, names] of byLocale) {
    const target = join(messagesDirectory, locale, 'index.ts');
    const expected = renderIndex(locale, names);
    const actual = existsSync(target) ? readFileSync(target, 'utf8') : null;
    if (actual === expected) {
      continue;
    }
    if (check) {
      problems.push(
        actual === null
          ? `messages/${locale}/index.ts is missing; run npm run i18n:index`
          : `messages/${locale}/index.ts is stale or damaged; run npm run i18n:index`,
      );
    } else {
      writeFileSync(target, expected, 'utf8');
      written.push(`messages/${locale}/index.ts`);
    }
  }
  return { problems, written };
}
